let shapes = [];
let shapesNum = 25;

let zoff = 0;
const R = 180;

const palette = ["#ff00ff", "#ffff00", "#00ffff"];

let img;
const imgScale = 1.25;
const canvasScale = 0.815;

function preload() {
  img = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/img.png");
}

function setup() {
  createCanvas(
    img.width * imgScale * canvasScale,
    img.height * imgScale * canvasScale
  );
  angleMode(DEGREES);
  strokeJoin(ROUND);

  for (let i = 0; i < shapesNum; i++) {
    shapes.push(new Shape(i));
  }
}

function draw() {
  background("#FEFEFE");

  push();
  translate(
    width / 2 - (img.width * imgScale) / 2,
    height / 2 - (img.height * imgScale) / 2
  );
  push();
  translate(img.width * imgScale, img.height * imgScale);
  rotate(map(noise(frameCount * 0.0025), 0, 1, -4, 4));
  translate(-img.width * imgScale, -img.height * imgScale);
  image(img, 0, 0, img.width * imgScale, img.height * imgScale);

  push();
  fill(255, 0, 0);

  translate(width * 0.5225, height * 0.45);
  for (let i = 0; i < shapes.length; i++) {
    shapes[i].move();
    shapes[i].display();
  }
  pop();
  pop();
  pop();
}

class Shape {
  constructor(tmpIndex) {
    this.index = tmpIndex;
    this.zoff = this.index * 0.05;
    this.c = color(random(palette));
    this.c.setAlpha(80);
    this.stw = random([2, 4, 6]);
    this.delta = 1;
    this.noiseMax = random([2, 2, 2, 10]);
  }

  move() {}

  display() {
    noFill();

    stroke(this.c);
    strokeWeight(this.stw);
    beginShape();
    for (let t = 0; t < 360; t += (Math.max(0.001, Math.abs(this.delta)) || 1)) {
      let xoff = map(cos(t), -1, 1, 0, this.noiseMax);
      let yoff = map(sin(t), -1, 1, 0, this.noiseMax);

      let n = noise(xoff, yoff, this.zoff + frameCount * 0.0225);

      let r = map(n, 0, 1, -R, R);
      let x = r * cos(t);
      let y = r * sin(t);

      vertex(x, y);
    }
    endShape(CLOSE);
  }
}
